<?php
/** По делу v1.8.0. Таблица клиентов. */
if(!defined('B_PROLOG_INCLUDED')||B_PROLOG_INCLUDED!==true){die();}$list=array_values(array_filter($allClients,static function($c)use($q){return $q===''||mb_stripos($c['UF_NAME'],$q)!==false;}));
?><div class="toolbar"><?php $filters(true); ?><a class="button primary" data-form="modal" href="<?=$h($url('/clients/new.php',['month'=>$month]))?>">+ Клиент</a></div><div class="result-strip"><span>В базе <b><?=count($allClients)?></b></span><span>Найдено <b><?=count($list)?></b></span></div><?php $rows=$paginate($list); ?><div class="table-wrap"><table><thead><tr><th>Клиент / сайт</th><th>Пакеты</th><th>Выделено</th><th>В пакетах</th><th>Отдельно</th><th>Доступно</th><th>Статус</th></tr></thead><tbody><?php foreach($rows as $c):$b=$r->balance((int)$c['ID'],$month); ?><tr><td><a class="row-link" data-nav href="<?=$h($url('/clients/detail.php',['client'=>(int)$c['ID'],'month'=>$month]))?>"><?=$h($c['UF_NAME'])?> ↗</a><small><?=$h($c['UF_SITE'])?></small></td><td><?=$b['count']?></td><td><?=$dur($b['limit'])?></td><td><?=$dur($b['packageSpent'])?></td><td><?=$dur($b['extra'])?></td><td><?=$b['count']?$dur($b['free']):'Нет пакетов'?><?php if($b['over']): ?><small class="warning">Перерасход <?=$dur($b['over'])?></small><?php endif; ?></td><td><span class="status <?=$c['UF_ACTIVE']?'done':''?>"><?=$c['UF_ACTIVE']?'Активен':'Неактивен'?></span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="empty">Клиенты не найдены.</td></tr><?php endif; ?></tbody></table></div>
